def find_first_non_identity(matrix):
    n = len(matrix)
    if n == 0:
        return -1

    for i in range(n):
        if len(matrix[i]) != n:
            return -1  # Not a square matrix, treat as invalid identity

        for j in range(n):
            expected = 1 if i == j else 0
            if matrix[i][j] != expected:
                return (i, j)

    return -1
