def convert_frequency_string(frequency_string):
    if not frequency_string:
        return ""

    result = []
    i = 0
    n = len(frequency_string)

    while i < n:
        # Parse the number
        num_start = i
        while i < n and frequency_string[i].isdigit():
            i += 1

        if num_start == i:
            # No number found before a letter
            return ""

        num_str = frequency_string[num_start:i]
        try:
            count = int(num_str)
        except ValueError:
            return ""

        # Check if there is a letter following the number
        if i >= n or not frequency_string[i].isalpha():
            return ""

        letter = frequency_string[i]
        i += 1  # Move past the letter

        if count > 0:
            result.append(letter * count)

    return "".join(result)
