import os
import glob
from datetime import datetime

def get_mtime(dir_path):
    """
    Retrieves the most recent file modification time (mtime) from a directory path.

    Args:
        dir_path (str): Path to the directory to scan.

    Returns:
        datetime or None: The datetime object of the most recently modified file/directory,
                          or None if the directory is empty or invalid.
    """
    try:
        if not os.path.isdir(dir_path):
            return None

        max_mtime = None

        # Walk through the directory recursively
        for root, dirs, files in os.walk(dir_path):
            # Check directories
            for d in dirs:
                dir_path_full = os.path.join(root, d)
                try:
                    mtime = os.path.getmtime(dir_path_full)
                    if max_mtime is None or mtime > max_mtime:
                        max_mtime = mtime
                except (OSError, PermissionError):
                    continue

            # Check files
            for f in files:
                file_path_full = os.path.join(root, f)
                try:
                    mtime = os.path.getmtime(file_path_full)
                    if max_mtime is None or mtime > max_mtime:
                        max_mtime = mtime
                except (OSError, PermissionError):
                    continue

        if max_mtime is None:
            return None

        return datetime.fromtimestamp(max_mtime)

    except Exception:
        return None
