def generalized_recursive_operation(nums, op):
    if op not in ("add", "sub", "mul", "div"):
        raise ValueError("Operator must be one of 'add', 'sub', 'mul', 'div'")

    if len(nums) < 2:
        raise ValueError("List must contain at least two numbers")

    def apply_op(a, b):
        if op == "add":
            return a + b
        elif op == "sub":
            return a - b
        elif op == "mul":
            return a * b
        elif op == "div":
            if b == 0:
                raise ZeroDivisionError("Division by zero")
            return a / b

    # Pair adjacent numbers and apply the operator to each pair
    pairs = [(nums[i], nums[i+1]) for i in range(len(nums) - 1)]

    # Apply the operator to each pair
    results = [apply_op(a, b) for a, b in pairs]

    # If there's only one pair, return the result directly
    if len(results) == 1:
        return results[0]

    # Recursively apply the operator to the results
    return generalized_recursive_operation(results, op)
```

