def generate_escape_codes(foreground=None, background=None, bold=False, italic=False, underline=False, cursor_position=None, clear=False):
    codes = []

    if foreground is not None:
        codes.append(f"\u001b[38;2;{foreground[0]};{foreground[1]};{foreground[2]}m")

    if background is not None:
        codes.append(f"\u001b[48;2;{background[0]};{background[1]};{background[2]}m")

    if bold:
        codes.append("\u001b[1m")

    if italic:
        codes.append("\u001b[3m")

    if underline:
        codes.append("\u001b[4m")

    if cursor_position is not None:
        x, y = cursor_position
        codes.append(f"\u001b[{x};{y}H")

    if clear:
        codes.append("\u001b[2J")

    return "".join(codes)
