import json

def format_text_attribute_as_markdown(json_string: str) -> str:
    """
    Parses a JSON string containing an object with a 'text' attribute and returns
    the 'text' attribute formatted as Markdown.

    - If 'text' is a string, returns it as-is.
    - If 'text' is an array, joins elements with newlines.
    - If 'text' is an object, converts each key-value pair to a Markdown table row.

    Args:
        json_string (str): A JSON string containing an object with a 'text' attribute.

    Returns:
        str: The 'text' attribute formatted as Markdown.
    """
    try:
        data = json.loads(json_string)
    except json.JSONDecodeError:
        return ""

    if not isinstance(data, dict):
        return ""

    text = data.get("text")

    if text is None:
        return ""

    if isinstance(text, str):
        return text
    elif isinstance(text, list):
        return "\n".join(str(item) for item in text)
    elif isinstance(text, dict):
        if not text:
            return ""

        # Create table header
        lines = ["| Key | Value |", "| --- | --- |"]

        for key, value in text.items():
            # Escape pipes and newlines in key and value for safe Markdown
            key_escaped = str(key).replace("|", "\\|").replace("\n", "\\n")
            value_escaped = str(value).replace("|", "\\|").replace("\n", "\\n")
            lines.append(f"| {key_escaped} | {value_escaped} |")

        return "\n".join(lines)
    else:
        return str(text)
```

