        TypeError: If the input is not a torch.Tensor.
        RuntimeError: If the tensor is on a non-CUDA device and cannot be moved to CPU.
        ValueError: If the provided device is invalid or not a CPU device.
    """
    if not isinstance(tensor, torch.Tensor):
        raise TypeError("Input must be a torch.Tensor.")

    if tensor.device.type == "cpu":
        return tensor

    if device is not None:
        try:
            device_obj = torch.device(device)
        except Exception as e:
            raise ValueError(f"Invalid device specification: {device}") from e

        if device_obj.type != "cpu":
            raise ValueError(f"Provided device '{device}' is not a CPU device.")

        try:
            return tensor.cpu()
        except Exception as e:
            raise RuntimeError(f"Failed to transfer tensor to CPU: {e}") from e

    # If no device is provided and tensor is not on CPU, attempt default CPU transfer
    try:
        return tensor.cpu()
    except Exception as e:
        raise RuntimeError(f"Failed to transfer tensor to CPU: {e}") from e
