import json

def sum_nested_values(file_path):
    try:
        with open(file_path, 'r') as f:
            data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError, IOError):
        return 0

    total = 0

    def traverse(obj):
        nonlocal total
        if isinstance(obj, dict):
            if "a" in obj and "c" in obj:
                # obj["a"] should be an array, obj["c"] is the object context
                if isinstance(obj["a"], list):
                    for item in obj["a"]:
                        if isinstance(item, (int, float)) and not isinstance(item, bool):
                            total += item
            # Continue traversing deeper if needed, but per spec we only care about this specific structure
            for value in obj.values():
                traverse(value)
        elif isinstance(obj, list):
            for item in obj:
                traverse(item)

    traverse(data)
    return total
