import re

def filter_rules(events, rules):
    def matches_rule(event, rule):
        for key, pattern in rule:
            if key not in event:
                return False
            value = event[key]
            if isinstance(pattern, str) and pattern.startswith('.*') and pattern.endswith('$'):
                regex_pattern = pattern[2:-1]
                if not re.search(regex_pattern, value):
                    return False
            elif pattern != value:
                return False
        return True

    matched_events = []
