import numpy as np

def convert_to_3d(x):
    """
    Converts a 2D grayscale or 3D RGB image array into a 3D array with a leading dimension.

    If x is 2D (grayscale), returns shape (1, H, W).
    If x is 3D (RGB), returns shape (3, H, W).
    The result is a deep copy of x.

    Parameters:
        x (np.ndarray): Input image array.

    Returns:
        np.ndarray: New array with leading dimension 1 or 3.
    """
    if x.ndim == 2:
        # Grayscale: add leading dimension of size 1
        return np.stack([x], axis=0).copy()
    elif x.ndim == 3 and x.shape[0] == 3:
        # RGB: reorder to (3, H, W) if it's currently (H, W, 3)
        if x.shape[0] == 3:
            # Already in (3, H, W) format
            return x.copy()
        else:
            # Assume (H, W, 3) and transpose to (3, H, W)
            return x.transpose(2, 0, 1).copy()
    else:
        raise ValueError("Input array must be 2D (grayscale) or 3D with 3 channels (RGB).")
