def create_dict_from_str(string: str) -> dict:
    if not string or not string.strip():
        return {}

    result = {}
    pairs = string.split(',')

    for pair in pairs:
        pair = pair.strip()
        if not pair:
            continue

        if '=' not in pair:
            return {}

        key, _, value = pair.partition('=')
        key = key.strip()
        value = value.strip()

        if not key:
            return {}

        # Convert value to appropriate type if possible
        try:
            if value.lower() == 'true':
                result[key] = True
            elif value.lower() == 'false':
                result[key] = False
            elif value.isdigit() or (value.startswith('-') and value[1:].isdigit()):
                result[key] = int(value)
            else:
                # Try float conversion
                try:
                    result[key] = float(value)
                except ValueError:
                    result[key] = value
        except Exception:
            result[key] = value

    return result
