def bit_string_to_byte(bit_string):
    # Validate input: must be a string containing only '0' and '1'
    if not isinstance(bit_string, str):
        raise TypeError("Input must be a string.")

    if not all(c in '01' for c in bit_string):
        raise ValueError("Input string must contain only '0' and '1'.")

    # Pad the bit string to the nearest multiple of 8 with leading zeros
    length = len(bit_string)
    if length == 0:
        return 0

    padding_needed = (8 - (length % 8)) % 8
    padded_bit_string = '0' * padding_needed + bit_string

    # Convert binary string to integer
    return int(padded_bit_string, 2)
