from typing import List, Callable, Any, Awaitable
import asyncio

def promise_list(functions: List[Callable]) -> Callable[[object], List[object]]:
    """
    Creates a function that takes a value, applies it to each function in the list,
    and returns a list of promises (mocked) that are resolved when the callbacks are completed.

    The callbacks are expected to accept the value and a callback function that receives
    the result to signal completion.

    Args:
        functions: A list of functions to apply to the input value.

    Returns:
        A function that takes a value and returns a list of resolved promises.
    """
    def wrapper(value: Any) -> List[Any]:
        results = []

        for func in functions:
            # Create a mock promise object
            class MockPromise:
                def __init__(self, result):
                    self._result = result
                    self._resolved = False

                def then(self, on_fulfilled, on_rejected):
                    if self._resolved:
                        try:
                            on_fulfilled(self._result)
                        except Exception as e:
                            on_rejected(e)
                    return self

                def resolve(self, result):
                    self._result = result
                    self._resolved = True

                def reject(self, error):
                    self._result = error
                    self._resolved = True

                @property
                def state(self):
                    return "pending" if not self._resolved else "resolved"

            promise = MockPromise(None)

            # Create a callback that resolves the promise
            def callback(result):
                promise.resolve(result)

            # Apply the function with the value and callback
            try:
                func(value, callback)
            except Exception as e:
                promise.reject(e)

            results.append(promise)

        return results

    return wrapper
