def convert_path_to_dict(path):
    # Remove leading/trailing whitespace and handle edge cases
    path = path.strip()

    # Handle empty path or root-only path
    if not path or path == "/":
        return {}

    # Remove leading slash if present
    if path.startswith("/"):
        path = path[1:]

    # Split the path into components
    parts = path.split("/")

    # Filter out empty strings that might result from consecutive slashes
    parts = [part for part in parts if part]

    # If no parts remain, return empty dict
    if not parts:
        return {}

    # Build the nested dictionary
    result = {}
    current = result

    for part in parts:
        current[part] = True if part == parts[-1] else {}
        current = current[part]

    return result
