def longest_matching_substring(str1, str2):
    if not str1 or not str2:
        return ""

    n, m = len(str1), len(str2)
    # dp[i][j] = length of longest common suffix of str1[:i] and str2[:j]
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    best_len = 0
    best_end = 0  # end index in str1 (exclusive)

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                if dp[i][j] > best_len:
                    best_len = dp[i][j]
                    best_end = i
            else:
                dp[i][j] = 0

    if best_len == 0:
        return ""

    return str1[best_end - best_len:best_end]
