def search_special_dict(search_key, special_dict):
    if not isinstance(special_dict, dict):
        return None

    # If the search key is None, we only check the None key directly
    if search_key is None:
        return special_dict.get(None)

    # If the search key is a string, we search among string keys and recurse
    if isinstance(search_key, str):
        for k, v in special_dict.items():
