def parse_string_with_quoted_values(string):
    if not string:
        return []

    result = []
    current_value = []
    in_single_quote = False
    in_double_quote = False
    i = 0

    while i < len(string):
        char = string[i]

        if in_single_quote:
            if char == "'":
                # End of single-quoted section
                in_single_quote = False
            else:
                current_value.append(char)
        elif in_double_quote:
            if char == '"':
                # End of double-quoted section
                in_double_quote = False
            else:
                current_value.append(char)
        else:
            # Not inside any quotes
            if char == "'":
                in_single_quote = True
            elif char == '"':
                in_double_quote = True
            elif char == ',':
                # End of current value
                result.append(''.join(current_value))
                current_value = []
            else:
                current_value.append(char)

        i += 1

    # Append the last value if there is any remaining content
    if current_value:
        result.append(''.join(current_value))

    return result
