def flatten_config_file(config_file_path):
    """
    Reads a configuration file in key=value format and returns a dictionary.
    If a key appears multiple times, its values are collected into a list.

    Args:
        config_file_path (str): Path to the configuration file.

    Returns:
        dict: Dictionary with keys mapping to either a single value or a list of values.
    """
    config = {}

    try:
        with open(config_file_path, 'r', encoding='utf-8') as file:
            for line in file:
                line = line.strip()
                # Skip empty lines and comments
                if not line or line.startswith('#'):
                    continue

                if '=' not in line:
                    continue

                key, value = line.split('=', 1)
                key = key.strip()
                value = value.strip()

                if key in config:
                    if isinstance(config[key], list):
                        config[key].append(value)
                    else:
                        config[key] = [config[key], value]
                else:
                    config[key] = value
    except FileNotFoundError:
        raise FileNotFoundError(f"Configuration file not found: {config_file_path}")
    except Exception as e:
