def calculate_sequence_length(maximum_value: int) -> int:
    if maximum_value < 1:
        raise ValueError("maximum_value must be at least 1")

    a = 1
    n = 1
    max_val = a
    max_index = 1

    while True:
        if n % 2 == 0:
            a = a / 2
        else:
            a = a / 2 + 1

        n += 1
        if a > max_val:
            max_val = a
            max_index = n

        if a == maximum_value and a > max_val:
            # This case can't happen because we update max_val immediately
            # when a exceeds the current max.
            pass

        # Stop when we have seen the maximum_value as the new maximum
        if a == maximum_value and a >= max_val:
            # Ensure this is the first time we reach this maximum
            if max_val == maximum_value:
                break
            # If we just updated max_val to maximum_value, we are done
            if max_val == maximum_value:
                break

        # Safety break to avoid infinite loops in unexpected cases
        if n > 10000:
            break

    return max_index
