    base_map = {
        'hex': 16,
        'bin': 2,
        'oct': 8,
        'dec': 10
    }

    # Split the input string by spaces to get individual tokens
    tokens = input_string.split()
    result_parts = []

    for token in tokens:
        # Find the prefix and the number part
        prefix = None
        number_part = None

        for base_name, base in base_map.items():
            if token.startswith(base_name):
                prefix = base_name
                number_part = token[len(base_name):]
                break

        if prefix is None or not number_part:
            continue  # Skip tokens that don't match any known format

        try:
            # Convert the number from its base to decimal
            decimal_value = int(number_part, base)
            result_parts.append(str(decimal_value))
        except ValueError:
            # Skip invalid number formats
            continue

    return " ".join(result_parts)
