import json

def traverse(s, d):
    """
    Parses a JSON string `s` and traverses it using the field path specified in `d['field']`.
    If the path exists and matches the expected value (optional check via d['value']),
    returns a list containing the matched value(s). Otherwise, returns an empty list.

    The field path in d['field'] uses dot notation (e.g., "product.price").
    """
    try:
        data = json.loads(s)
    except json.JSONDecodeError:
        return []

    path_parts = d.get("field", "").strip().split(".")
    current = data

    for part in path_parts:
        if isinstance(current, dict) and part in current:
            current = current[part]
        else:
            return []

    # Optional: if d['value'] is provided, verify the matched value
    if "value" in d and d["value"] is not None:
        if current != d["value"]:
            return []

    # If the final value is a list, return all items; otherwise wrap in a list
    if isinstance(current, list):
        return list(current)
    return [current]
