def mse_mae(y_true, y_pred):
    # Reshape y_pred to match the shape of y_true
    y_pred = y_pred.reshape(y_true.shape)

    # Dictionary of loss functions
    loss_functions = {
        (2,): lambda y_t, y_p: np.mean((y_t - y_p) ** 2),  # MSE for 2D
        (1,): lambda y_t, y_p: np.mean(np.abs(y_t - y_p))   # MAE for 1D
