import os
import subprocess

def change_permissions(folder_path, mode):
    """
    Recursively changes the access permissions of all files and folders within
    the specified folder to the given mode using the UNIX chmod command.

    Args:
        folder_path (str): Path to the root folder.
        mode (str): Permission mode string (e.g., '755', '644', 'rwxr-xr-x').
    """
    if not os.path.isdir(folder_path):
        raise ValueError(f"The path '{folder_path}' is not a valid directory.")

    for root, dirs, files in os.walk(folder_path):
        # Process directories
        for d in dirs:
            dir_path = os.path.join(root, d)
            try:
                subprocess.run(['chmod', mode, dir_path], check=True)
            except subprocess.CalledProcessError as e:
                raise RuntimeError(f"Failed to change permissions for directory '{dir_path}': {e}")

        # Process files
        for f in files:
            file_path = os.path.join(root, f)
            try:
                subprocess.run(['chmod', mode, file_path], check=True)
            except subprocess.CalledProcessError as e:
                raise RuntimeError(f"Failed to change permissions for file '{file_path}': {e}")
