    with open(filename, 'r', encoding='utf-8') as f:
        while True:
            block = f.read(1024)
            if not block:
                break

            # Process lines in the current block
            # We need to handle lines that might be split across blocks
            # by keeping track of the last incomplete line
            lines_buffer = []
            current_line = ""

            for char in block:
                current_line += char
                if char == '\n':
                    lines_buffer.append(current_line)
                    current_line = ""

            if current_line:
                lines_buffer.append(current_line)

            # Process complete lines from the buffer
