def get_nearest_element(lst, k):
    # Precondition checks
    if not isinstance(lst, list):
        raise TypeError("The first argument must be a list.")
    if not all(isinstance(x, int) for x in lst):
        raise TypeError("All elements in the list must be integers.")
    if not isinstance(k, int):
        raise TypeError("The second argument must be an integer.")

    # If the list is empty, there is no element to return
    if not lst:
        raise ValueError("The list cannot be empty.")

    # Since the list is sorted in ascending order, we can use binary search
    # to find the position where k would be inserted to maintain order.
    # We want the largest element <= k.

    left, right = 0, len(lst) - 1
    result = None

    while left <= right:
        mid = (left + right) // 2
        if lst[mid] <= k:
            result = lst[mid]
            left = mid + 1  # Try to find a larger element still <= k
        else:
            right = mid - 1  # This element is greater than k, look to the left

    if result is None:
        # This case happens if all elements are greater than k
        raise ValueError("No element in the list is less than or equal to k.")

    return result
