def prefix_filter(nested_dict: dict, prefix: str) -> dict:
    """
    Filters a nested dictionary to return only keys that start with the given prefix.

    The function recursively processes nested dictionaries and lists/tuples,
    preserving the structure while updating keys to start with the prefix.

    Args:
        nested_dict (dict): The input nested dictionary.
        prefix (str): The prefix string to filter keys by.

    Returns:
        dict: A new dictionary containing only keys that start with the prefix,
              with updated keys and preserved nested structure.
    """
    result = {}

    for key, value in nested_dict.items():
        if isinstance(key, str) and key.startswith(prefix):
            new_key = key
            if isinstance(value, dict):
                filtered_value = prefix_filter(value, prefix)
                if filtered_value:
                    new_key = f"{prefix}_{key[len(prefix):]}"
                    result[new_key] = filtered_value
            elif isinstance(value, (list, tuple)):
                # For lists/tuples, we filter their elements if they are dicts
                filtered_list = []
                for item in value:
                    if isinstance(item, dict):
                        filtered_item = prefix_filter(item, prefix)
                        if filtered_item:
                            filtered_list.append(filtered_item)
                if filtered_list:
                    new_key = f"{prefix}_{key[len(prefix):]}"
                    result[new_key] = filtered_list
            else:
                new_key = f"{prefix}_{key[len(prefix):]}"
                result[new_key] = value
        elif isinstance(value, dict):
            # Recursively process nested dicts even if current key doesn't match prefix
            filtered_value = prefix_filter(value, prefix)
            if filtered_value:
                new_key = f"{prefix}_{key[len(prefix):]}" if key.startswith(prefix) else key
                result[new_key] = filtered_value
        elif isinstance(value, (list, tuple)):
            filtered_list = []
            for item in value:
                if isinstance(item, dict):
                    filtered_item = prefix_filter(item, prefix)
                    if filtered_item:
                        filtered_list.append(filtered_item)
            if filtered_list:
                new_key = f"{prefix}_{key[len(prefix):]}" if key.startswith(prefix) else key
                result[new_key] = filtered_list

    return result

