```python
def binary_search(arr, target):
    """
    Finds the index of a target value in a sorted array using binary search.
    Returns the index if found, otherwise returns -1.
    """
    # Error handling for invalid inputs
    if not isinstance(arr, list):
        raise TypeError("Input array must be a list.")
    if not all(isinstance(x, (int, float)) for x in arr):
        raise TypeError("All elements in the array must be numbers.")
    if not all(arr[i] <= arr[i+1] for i in range(len(arr)-1)):
        raise ValueError("Input array must be sorted in ascending order.")
    if not isinstance(target, (int, float)):
        raise TypeError("Target must be a number.")

    def find_midpoint(left, right):
        """Calculates the midpoint index."""
        return (left + right) // 2

    def is_target_at_midpoint(mid, arr, target):
        """Checks if the target is at the midpoint."""
        return arr[mid] == target

    def recurse_left(left, right, arr, target):
        """Recursively searches the left half."""
        if left > right:
            return -1
        mid = find_midpoint(left, right)
        if is_target_at_midpoint(mid, arr, target):
            return mid
        elif arr[mid] > target:
            return recurse_left(left, mid - 1, arr, target)
        else:
            return recurse_left(mid + 1, right, arr, target)

    def recurse_right(left, right, arr, target):
        """Recursively searches the right half."""
        if left > right:
            return -1
        mid = find_midpoint(left, right)
        if is_target_at_midpoint(mid, arr, target):
            return mid
        elif arr[mid] < target:
            return recurse_right(mid + 1, right, arr, target)
        else:
            return recurse_right(left, mid - 1, arr, target)

    if not arr:
        return -1

    return recurse_left(0, len(arr) - 1, arr, target)
```

