```python
def shunting_yard(input_string: str) -> str:
    """
    Convert an infix arithmetic expression to postfix (Reverse Polish) notation
    using Dijkstra's Shunting Yard algorithm.

    Supported operators: +, -, *, /
    Parentheses: (, )
    Operands: integers (no negative numbers or decimals in this implementation)
    """
    import re

    tokens = re.findall(r'\d+|[+\-*/()]', input_string)

    precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2,
    }

    output = []
    operator_stack = []

    for token in tokens:
        if token.isdigit():
            output.append(token)
        elif token in precedence:
            while (
                operator_stack
                and operator_stack[-1] != '('
                and precedence.get(operator_stack[-1], 0) >= precedence[token]
            ):
                output.append(operator_stack.pop())
            operator_stack.append(token)
        elif token == '(':
            operator_stack.append(token)
        elif token == ')':
            while operator_stack and operator_stack[-1] != '(':
                output.append(operator_stack.pop())
            if not operator_stack or operator_stack[-1] != '(':
                raise ValueError("Mismatched parentheses")
            operator_stack.pop()  # discard '('
        else:
            raise ValueError(f"Unknown token: {token}")

    while operator_stack:
        top = operator_stack.pop()
        if top in ('(', ')'):
            raise ValueError("Mismatched parentheses")
        output.append(top)

    return ' '.join(output)
```

