def get_candidates(puzzle):
    """
    Given a 9x9 Sudoku puzzle matrix with some cells filled and some empty,
    return a 9x9 matrix where:
      - If the cell is filled, the entry is 'X'.
      - If the cell is empty, the entry is a list of possible values (1-9)
        that do not conflict with the current row, column, and 3x3 box.
    """
    def is_valid(value, row, col, board):
        # Check row
        if value in board[row]:
            return False
        # Check column
        if any(board[r][col] == value for r in range(9)):
            return False
        # Check 3x3 box
        box_row, box_col = 3 * (row // 3), 3 * (col // 3)
        for r in range(box_row, box_row + 3):
            for c in range(box_col, box_col + 3):
                if board[r][c] == value:
                    return False
        return True

    candidates = []
    for r in range(9):
        row_candidates = []
        for c in range(9):
            if puzzle[r][c] != 0:
                row_candidates.append('X')
            else:
                possible = [v for v in range(1, 10) if is_valid(v, r, c, puzzle)]
                row_candidates.append(possible)
        candidates.append(row_candidates)

    return candidates
```

