import heapq
from typing import List

def find_top_k_numbers(numbers: List[int], k: int) -> List[int]:
    if not numbers:
        raise ValueError("Input list cannot be empty.")
    if k <= 0:
        raise ValueError("K must be a positive integer.")
    if k > len(numbers):
        raise ValueError("K cannot be greater than the number of elements in the list.")

    # Use a min-heap of size k to keep the largest k elements
    heap = numbers[:k]
    heapq.heapify(heap)

    for num in numbers[k:]:
        if num > heap[0]:
            heapq.heapreplace(heap, num)

    # The heap contains the k largest elements, but not necessarily sorted
    return sorted(heap, reverse=True)
