from typing import List

def sort_and_deduplicate(input: List[int]) -> List[int]:
    # Validate input: ensure all elements are integers
    for item in input:
        if not isinstance(item, int):
            raise TypeError(f"All elements must be integers, found {type(item).__name__}")

    # Use a set to deduplicate while preserving the first occurrence order
    seen = set()
    unique_ordered = []
    for item in input:
        if item not in seen:
            seen.add(item)
            unique_ordered.append(item)

    # Sort in decreasing order; since we only care about values,
    # stability among equal values is irrelevant after deduplication.
    return sorted(unique_ordered, reverse=True)
