        if not isinstance(params, dict):
            return ""

        if not params:
            return ""

        query_parts = []
        for key, value in params.items():
            if not isinstance(key, str):
                return ""

            if not isinstance(value, (str, int, float, bool)) and value is not None:
                return ""

            if value is None:
                continue

            # Convert value to string
            str_value = str(value)

            # URL encode key and value
