def read_int64(filename, endianness):
    """
    Reads a 64-bit signed integer from a binary file with the specified endianness.

    Parameters:
        filename (str): Path to the binary file.
        endianness (str): Either 'little' or 'big' indicating byte order.

    Returns:
        int: The 64-bit signed integer read from the file.

    Raises:
        ValueError: If endianness is not 'little' or 'big', or if the file does not contain at least 8 bytes.
        FileNotFoundError: If the file does not exist.
        IOError: If there is an error reading the file.
    """
    if endianness not in ('little', 'big'):
        raise ValueError("Endianness must be 'little' or 'big'.")

    try:
        with open(filename, 'rb') as f:
            data = f.read(8)
    except FileNotFoundError:
        raise FileNotFoundError(f"The file '{filename}' does not exist.")
    except IOError as e:
        raise IOError(f"Error reading file '{filename}': {e}")

    if len(data) < 8:
        raise ValueError(f"File does not contain enough bytes to read a 64-bit integer (found {len(data)} bytes, expected 8).")

    if endianness == 'little':
        return int.from_bytes(data[:8], byteorder='little', signed=True)
    else:
        return int.from_bytes(data[:8], byteorder='big', signed=True)
