        if not isinstance(update, dict):
            base.update(update)
            return

        for key, value in update.items():
            if key not in base:
                if value is None:
                    continue
                base[key] = value
            else:
                existing_value = base[key]
                if isinstance(existing_value, dict) and isinstance(value, dict):
