def longest_contiguous_sequence(nums):
    if not nums:
        return []

    max_length = 0
    best_start = 0
    best_end = 0

    seen = {}
    start = 0

    for end, num in enumerate(nums):
        if num in seen and seen[num] >= start:
            start = seen[num] + 1
        seen[num] = end

        current_length = end - start + 1
        if current_length > max_length:
            max_length = current_length
            best_start = start
            best_end = end

    return nums[best_start:best_end + 1]
```

