```python
def rook_coverage(board: str) -> int:
    """
    Returns the number of cells covered by at least one rook on the board.
    The board is a string of length 64 representing an 8x8 chessboard.
    '.' = empty cell, 'R' = rook.
    """
    if len(board) != 64:
        raise ValueError("Board must be a string of length 64.")

    covered = set()
    for i, cell in enumerate(board):
        if cell == 'R':
            row = i // 8
            col = i % 8
            # Cover entire row
            for c in range(8):
                covered.add(row * 8 + c)
            # Cover entire column
            for r in range(8):
                covered.add(r * 8 + col)

    return len(covered)
```

