def convert_ipv4_address(address: str) -> int:
    try:
        parts = address.split('.')
        if len(parts) != 4:
            return -1

        octets = []
        for part in parts:
            # Check if part is a valid integer string
            if not part.isdigit():
                return -1
            num = int(part)
            if num < 0 or num > 255:
                return -1
            octets.append(num)

        # Convert to integer: (o1 << 24) + (o2 << 16) + (o3 << 8) + o4
        result = (octets[0] << 24) + (octets[1] << 16) + (octets[2] << 8) + octets[3]
        return result

    except Exception:
        return -1
