def check_magic_square(square):
    # Check if the input is a valid square matrix
    n = len(square)
    if n == 0:
        return False
    for row in square:
        if len(row) != n:
            return False

    # Calculate the target sum from the first row
    target_sum = sum(square[0])

    # Check all rows
    for row in square:
        if sum(row) != target_sum:
            return False

    # Check all columns
    for col_idx in range(n):
        col_sum = sum(square[row_idx][col_idx] for row_idx in range(n))
        if col_sum != target_sum:
            return False

    # Check main diagonal
    main_diag_sum = sum(square[i][i] for i in range(n))
    if main_diag_sum != target_sum:
        return False

    # Check anti-diagonal
    anti_diag_sum = sum(square[i][n - 1 - i] for i in range(n))
    if anti_diag_sum != target_sum:
        return False

    return True
