def convert_values_to_float(data):
    """
    Converts each numerical value in the 'data' list to a float.

    Parameters:
        data (dict): A dictionary containing a 'data' key with a list of dictionaries.

    Returns:
        dict: The same dictionary structure with all numerical values in the 'data' list converted to floats.

    Raises:
        ValueError: If a non-numerical value is encountered where a number is expected.
    """
    if not isinstance(data, dict):
        raise ValueError("Input must be a dictionary.")

    if 'data' not in data:
        raise ValueError("The input dictionary must contain a 'data' key.")

    if not isinstance(data['data'], list):
        raise ValueError("The 'data' key must contain a list.")

    result = data.copy()
    result['data'] = []

    for i, item in enumerate(data['data']):
        if not isinstance(item, dict):
            raise ValueError(f"Item at index {i} in 'data' list is not a dictionary.")

        converted_item = {}
        for key, value in item.items():
            if isinstance(value, (int, float)):
                converted_item[key] = float(value)
            elif value is None:
                raise ValueError(f"Non-numerical value (None) encountered at key '{key}' in item at index {i}.")
            else:
                raise ValueError(f"Non-numerical value '{value}' (type: {type(value).__name__}) encountered at key '{key}' in item at index {i}.")

        result['data'].append(converted_item)

    return result
