import numpy as np

def forward_prop(inputs, parameters):
    """
    Forward propagate an input through a neural network defined by the given parameters.

    Args:
        inputs (np.ndarray): Input data for the neural network.
        parameters (list): List of parameter tuples, where each tuple contains:
            - weights (np.ndarray): Weights for the layer.
            - biases (np.ndarray): Biases for the layer.
            - activation (str): Activation function name ('sigmoid', 'tanh', 'relu', 'linear').

    Returns:
        np.ndarray: Output of the neural network after forward propagation.
    """
    def activation(x, name):
        if name == 'sigmoid':
            return 1 / (1 + np.exp(-x))
        elif name == 'tanh':
            return np.tanh(x)
        elif name == 'relu':
            return np.maximum(0, x)
        elif name == 'linear':
            return x
        else:
            raise ValueError(f"Unsupported activation function: {name}")

    current = inputs
    for weights, biases, activation_name in parameters:
        current = current @ weights + biases
        current = activation(current, activation_name)

    return current
```

