def add_tuples_elementwise(tuple1, tuple2):
    len1 = len(tuple1)
    len2 = len(tuple2)
    max_len = max(len1, len2)

    # Pad the shorter tuple with zeros
    if len1 < max_len:
        tuple1 = tuple1 + (0,) * (max_len - len1)
    if len2 < max_len:
        tuple2 = tuple2 + (0,) * (max_len - len2)

    # Element-wise addition
    return tuple(a + b for a, b in zip(tuple1, tuple2))
