def atoi(string):
    INT_MIN = -2**31
    INT_MAX = 2**31 - 1

    s = string.strip()
    if not s:
        return 0

    index = 0
    sign = 1

    if s[index] == '-':
        sign = -1
        index += 1
    elif s[index] == '+':
        index += 1

    result = 0
    while index < len(s):
        ch = s[index]
        if '0' <= ch <= '9':
            digit = ord(ch) - ord('0')
            # Check for overflow before multiplying and adding
            if sign == 1:
                if result > (INT_MAX - digit) // 10:
                    return INT_MAX
            else:
                if result < (INT_MIN + digit) // 10:
                    return INT_MIN
            result = result * 10 + digit
        else:
            break
        index += 1

    return sign * result
