def convert_list_to_strings(numbers):
    if not numbers:
        return ""

    # Sort and remove duplicates to handle unordered or duplicate inputs
    sorted_numbers = sorted(set(numbers))

    ranges = []
    start = sorted_numbers[0]
    end = start

    for num in sorted_numbers[1:]:
        if num == end + 1:
            end = num
        else:
            if start == end:
                ranges.append(str(start))
            else:
                ranges.append(f"{start}-{end}")
            start = num
            end = num

    # Append the last range
    if start == end:
        ranges.append(str(start))
    else:
        ranges.append(f"{start}-{end}")

    return ", ".join(ranges)
