def extract_fasta(file_path):
    """
    Extract data from a FASTA file.

    Args:
        file_path (str): Path to the input FASTA file.

    Returns:
        list: A list of dictionaries, where each dictionary contains:
            - 'id': The sequence identifier (from the line starting with '>')
            - 'sequence': The corresponding DNA/protein sequence
    """
    import os

    if not os.path.exists(file_path):
        return []

    sequences = []
    current_id = None
    current_sequence = []

    try:
        with open(file_path, 'r') as file:
            for line in file:
                line = line.strip()
                if not line:
                    continue

                if line.startswith('>'):
                    # Save previous sequence if exists
                    if current_id is not None:
                        sequences.append({
                            'id': current_id,
                            'sequence': ''.join(current_sequence)
                        })

                    # Start new sequence
                    current_id = line[1:].strip()
                    current_sequence = []
                else:
                    current_sequence.append(line)

            # Don't forget the last sequence
            if current_id is not None:
                sequences.append({
                    'id': current_id,
                    'sequence': ''.join(current_sequence)
                })
    except Exception:
        return []

    return sequences
