def zero_warn(msg, warning_level):
    def decorator(func):
        call_count = 0
        threshold = 100 if warning_level == 2 else 1000 if warning_level == 3 else 1

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal call_count
            result = func(*args, **kwargs)
            call_count += 1

            if result == 0:
                if call_count % threshold == 0:
                    print(msg)
            return result

        return wrapper

