def validate_date(date_string):
    import re

    # Check format YYYY-MM-DD using regex
    if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', date_string):
        return False

    try:
        year, month, day = map(int, date_string.split('-'))
    except ValueError:
        return False

    # Year constraints
    if not (1900 <= year <= 2099):
        return False

    # Month constraints
    if not (1 <= month <= 12):
        return False

    # Determine max days for the month
    if month in [1, 3, 5, 7, 8, 10, 12]:
        max_day = 31
    elif month in [4, 6, 9, 11]:
        max_day = 30
    elif month == 2:
        # Leap year check for February
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            max_day = 29
        else:
            max_day = 28
    else:
        return False

    # Day constraints
    if not (1 <= day <= max_day):
        return False

    return True
