def collect_files(root_dir, ext_type):
    """
    Recursively traverse a directory and collect all files ending with a specific extension.

    Args:
        root_dir (str): The path of the directory to start traversal from.
        ext_type (str): The file extension to match (e.g., '.py', '.jpg').

    Returns:
        set: A set of absolute file paths that end with the specified extension.
    """
    import os

    if not ext_type.startswith('.'):
        ext_type = '.' + ext_type

    result = set()

    def _traverse(directory):
        try:
            entries = os.listdir(directory)
        except PermissionError:
            return

        for entry in entries:
            full_path = os.path.join(directory, entry)

            if os.path.isfile(full_path):
                if full_path.endswith(ext_type):
                    result.add(os.path.abspath(full_path))
            elif os.path.isdir(full_path):
                _traverse(full_path)

    _traverse(root_dir)
    return result
