def draw_graph(graph: Dict[str, Dict[str, str]]) -> str:
    """
    Converts an adjacency list representation of a graph into a DOT format string.

    Input format:
      graph = {
          "node_id": {
              "type": "source" | "destination" | "intermediate",
              "edges": {
                  "neighbor_id": "label"
              }
          },
          ...
      }

    Output:
      A string in DOT language format representing the graph.
    """
    lines = ["digraph G {"]

    # Process each node
    for node_id, node_info in graph.items():
        node_type = node_info.get("type", "intermediate")

        # Determine node style based on type
        if node_type == "source":
            node_style = 'style=filled, fillcolor=lightblue'
        elif node_type == "destination":
            node_style = 'style=filled, fillcolor=lightgreen'
        else:
            node_style = 'style=filled, fillcolor=lightyellow'

        lines.append(f'    "{node_id}" [{node_style}];')

    # Process edges
    for node_id, node_info in graph.items():
        edges = node_info.get("edges", {})
        for neighbor_id, label in edges.items():
            # Ensure both nodes exist in the graph (optional safety check)
            if neighbor_id not in graph:
                continue

            # Escape quotes in label if necessary
            escaped_label = label.replace('"', '\\"')
            edge_label = f' [label="{escaped_label}"]' if label else ""
            lines.append(f'    "{node_id}" -> "{neighbor_id}"{edge_label};')

    lines.append("}")
    return "\n".join(lines)
