def find_max_xor_pair(numbers: List[int]) -> Tuple[int, int]:
    if len(numbers) < 2:
        raise ValueError("Array must contain at least two elements.")

    # Determine the maximum number of bits needed
    max_val = max(numbers)
    if max_val == 0:
        # All numbers are 0; any distinct pair gives XOR 0
        return (numbers[0], numbers[1])

    max_bits = max_val.bit_length()

    # Trie to store binary representations of numbers
    trie = {}

    for num in numbers:
        node = trie
        for i in range(max_bits - 1, -1, -1):
            bit = (num >> i) & 1
            if bit not in node:
                node[bit] = {}
            node = node[bit]
        node['#'] = num  # Mark end of number

    best_a, best_b = None, None
    max_xor = -1

    for num in numbers:
        node = trie
        current_xor = 0
        candidate_b = num

        for i in range(max_bits - 1, -1, -1):
            bit = (num >> i) & 1
            desired = 1 - bit  # Prefer opposite bit to maximize XOR

            if desired in node:
                current_xor |= (1 << i)
                node = node[desired]
                candidate_b = node.get('#', candidate_b)
            else:
                # Must take same bit
                if bit not in node:
                    break  # Should not happen if trie is built correctly
                node = node[bit]
                # XOR bit is 0 here, so no change to current_xor

        if current_xor > max_xor:
            max_xor = current_xor
            best_a = num
            best_b = candidate_b

    return (best_a, best_b)
