def longest_common_subsequence(a, b):
    """
    Returns the longest common subsequence (LCS) of two strings a and b.
    Uses a recursive approach with memoization for efficiency.
    """
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def lcs_recursive(i, j):
        # Base case: if either index is out of bounds, return empty string
        if i == 0 or j == 0:
            return ""

        # If characters match, include this character and move both indices back
        if a[i - 1] == b[j - 1]:
            return a[i - 1] + lcs_recursive(i - 1, j - 1)
        else:
            # If not, take the max of excluding character from a or from b
            exclude_from_a = lcs_recursive(i, j - 1)
            exclude_from_b = lcs_recursive(i - 1, j)
            return exclude_from_a if len(exclude_from_a) > len(exclude_from_b) else exclude_from_b

    return lcs_recursive(len(a), len(b))
