def match_seq(seq, pattern):
    """
    Determine if the pattern matches the sequence character-wise.

    The pattern can contain:
    - '?' to match any single character
    - '*' to match a sequence of any length (including zero)

    Args:
        seq (str): The sequence to match against.
        pattern (str): The pattern containing characters, '?', and '*'.

    Returns:
        bool: True if the pattern matches the sequence, False otherwise.
    """
    def match(i, j):
        # i: index in seq, j: index in pattern
        if j == len(pattern):
            return i == len(seq)

        if i == len(seq):
            # Remaining pattern must be all '*'
            while j < len(pattern) and pattern[j] == '*':
                j += 1
            return j == len(pattern)

        if pattern[j] == '*':
            # Try matching zero characters or one or more characters
            # Option 1: treat '*' as matching zero characters
            if match(i, j + 1):
                return True
            # Option 2: treat '*' as matching one or more characters
            if i < len(seq) and match(i + 1, j):
                return True
            return False

        if pattern[j] == '?' or pattern[j] == seq[i]:
            return match(i + 1, j + 1)

        return False

    return match(0, 0)
