def validate_attr(attr_name, type_validator, value_validator):
    def decorator(func):
        def wrapper(self, *args, **kwargs):
            if not hasattr(self, attr_name):
                raise AttributeError(f"Attribute '{attr_name}' does not exist on object {self.__class__.__name__}.")

            attr_value = getattr(self, attr_name)

            # Validate type
