def normalize_annotations(obj, normalization_factor):
    """
    Normalizes the temporal scale of an object containing nested temporal annotations.

    Each annotation is a dictionary with 'start' and 'end' keys representing timestamps.
    The function creates a deep copy of the object and divides all start and end timestamps
    by the normalization_factor.

    Parameters:
    obj (dict): The object containing nested temporal annotations.
    normalization_factor (float): The factor by which to divide the timestamps.

    Returns:
    dict: A deep copy of the object with normalized timestamps.
    """
    import copy

    def normalize_timestamps(item):
        if isinstance(item, dict):
            # Check if this is a temporal annotation
            if 'start' in item and 'end' in item:
                item = copy.deepcopy(item)
                item['start'] = item['start'] / normalization_factor
                item['end'] = item['end'] / normalization_factor
            else:
                # Recursively process nested dictionaries
                return {k: normalize_timestamps(v) for k, v in item.items()}
        elif isinstance(item, list):
            return [normalize_timestamps(i) for i in item]
        else:
            return item

    return normalize_timestamps(copy.deepcopy(obj))
