def num_to_word(n):
    if not isinstance(n, int) or n < 0 or n > 999999999999:
        raise ValueError("Input must be an integer between 0 and 999,999,999,999")

    ones = [
        "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
        "seventeen", "eighteen", "nineteen"
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
    ]
    scales = ["", "thousand", "million", "billion"]

    def three_digits(num):
        if num == 0:
            return ""
        res = []
        h = num // 100
        rem = num % 100
        if h > 0:
            res.append(ones[h] + " hundred")
        if rem > 0:
            if rem < 20:
                res.append(ones[rem])
            else:
                t = rem // 10
                o = rem % 10
                res.append(tens[t])
                if o > 0:
                    res.append(ones[o])
        return " ".join(res)

    parts = []
    idx = 0
    while n > 0:
        chunk = n % 1000
        if chunk != 0:
            word = three_digits(chunk)
            if scales[idx]:
                word += " " + scales[idx]
            parts.append(word)
        n //= 1000
        idx += 1

    return " ".join(reversed(parts)) if parts else "zero"
