def calc_median(numbers):
    if not numbers:
        raise ValueError("Input list must not be empty.")

    n = len(numbers)
    # Use quickselect algorithm to find the k-th smallest element in O(n) average time
    def quickselect(arr, k):
        if len(arr) == 1:
            return arr[0]

        pivot = arr[len(arr) // 2]
        lows = [x for x in arr if x < pivot]
        highs = [x for x in arr if x > pivot]
        pivots = [x for x in arr if x == pivot]

        if k < len(lows):
            return quickselect(lows, k)
        elif k < len(lows) + len(pivots):
            return pivot
        else:
            return quickselect(highs, k - len(lows) - len(pivots))

    # For median, we need the element at index n//2 in 0-based sorted order
    # If n is odd, median is the middle element
    # If n is even, median is average of two middle elements
    if n % 2 == 1:
        return quickselect(numbers, n // 2)
    else:
        left = quickselect(numbers, n // 2 - 1)
        right = quickselect(numbers, n // 2)
        return (left + right) / 2
