def lucas(n):
    if n < 0:
        return None

    memo = {}

    def lucas_mod2(k):
        if k == 0:
            return 2 % 2  # F0 = 2 -> 0 mod 2
        if k == 1:
            return 1 % 2  # F1 = 1 -> 1 mod 2
        if k in memo:
            return memo[k]

        # Recursive step: Fk = F(k-1) + F(k-2)
        val = (lucas_mod2(k - 1) + lucas_mod2(k - 2)) % 2
        memo[k] = val
        return val

    return lucas_mod2(n)
