from datetime import datetime

def normalize_date(date_string):
    """
    Converts a date string into a normalized format YYYYMMDD.

    Supported formats:
    - YYYY-MM-DD
    - YYYY/MM/DD
    - YYYY.MM.DD
    - MM/DD/YY (ambiguous case)
    - MM-DD-YY (ambiguous case)
    - MM/DD/YYYY (ambiguous case)

    In ambiguous cases (e.g., "10/20/20"), the function assumes MM/DD/YY format.
    """
    date_string = date_string.strip()

    # Try standard YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD
    for fmt in ["%Y-%m-%d", "%Y/%m/%d", "%Y.%m.%d"]:
        try:
            dt = datetime.strptime(date_string, fmt)
            return dt.strftime("%Y%m%d")
        except ValueError:
            continue

    # Handle ambiguous formats: assume MM/DD/YY or MM-DD-YY
    # We'll try to parse as MM/DD/YY first
    for fmt in ["%m/%d/%y", "%m-%d-%y"]:
        try:
            dt = datetime.strptime(date_string, fmt)
            return dt.strftime("%Y%m%d")
        except ValueError:
            continue

    # If still not parsed, try MM/DD/YYYY (in case year is 4 digits but format is ambiguous)
    for fmt in ["%m/%d/%Y", "%m-%d-%Y"]:
        try:
            dt = datetime.strptime(date_string, fmt)
            return dt.strftime("%Y%m%d")
        except ValueError:
            continue

    raise ValueError(f"Unable to parse date string: {date_string}")
