def minmax_normalize(nums):
    if not nums:
        return []

    if len(nums) == 1:
        return nums[:]

    min_val = min(nums)
    max_val = max(nums)

    range_val = max_val - min_val

    if range_val == 0:
        # All elements are the same; normalize to 0
        return [0.0] * len(nums)

    normalized = []
    for x in nums:
        normalized.append((x - min_val) / range_val)

    return normalized
