def extract_word_at_position(sentence: str, position: int) -> str:
    if not sentence or position < 0:
        return ""

    words = []
    remaining = sentence

    while remaining:
        # Split by whitespace first
        left, sep, right = remaining.partition(" ")
        if left:
            # Further split the left part by punctuation
            word = left
            for punct in ".,;:!?()[]{}'\"-":
                if punct in word:
                    word = word.split(punct)[0]
            if word:
                words.append(word)
            remaining = right
        elif sep == " ":
            remaining = right
        else:
            # No space found; split by punctuation
            for punct in ".,;:!?()[]{}'\"-":
                if punct in remaining:
                    left, sep, right = remaining.partition(punct)
                    if left:
                        words.append(left)
                    remaining = right
                    break
            else:
                # No punctuation found either; take the rest as a word
                if remaining:
                    words.append(remaining)
                break

    if 0 <= position < len(words):
        return words[position]
    return ""
