def convert_string_to_base_b(s: str, b: int) -> int:
    try:
        if not isinstance(s, str) or not isinstance(b, int):
            return -1
        if b < 2 or b > 36:
            return -1
        if not s:
            return -1

        # Normalize input: strip whitespace
        s = s.strip()
        if not s:
            return -1

        # Check for valid characters for the given base
        valid_chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        s_upper = s.upper()
        for char in s_upper:
            if char not in valid_chars:
                return -1
            digit_value = valid_chars.index(char)
            if digit_value >= b:
                return -1

        # Convert manually to avoid locale or other issues
        result = 0
        for char in s_upper:
            digit_value = valid_chars.index(char)
            result = result * b + digit_value

        return result
    except Exception:
