def average_prices(prices, n=3):
    if not prices:
        return {}

    # Create a copy to avoid modifying the input list
    prices_copy = list(prices)

    # Calculate averages
    averages = {}
    for item in prices_copy:
        key = next(iter(item))
        value = item[key]
        averages[key] = value

    # Sort by average value in descending order and take top n
    sorted_items = sorted(averages.items(), key=lambda x: x[1], reverse=True)
    top_n = sorted_items[:n]

