import json
import csv

def convert_json_file_to_csv(json_file, csv_file):
    try:
        with open(json_file, 'r', encoding='utf-8') as f_in:
            data = json.load(f_in)

        if not isinstance(data, list):
            raise ValueError("JSON root must be a list of objects.")

        if len(data) == 0:
            with open(csv_file, 'w', newline='', encoding='utf-8') as f_out:
                pass
            return

        first_obj = data[0]
        if not isinstance(first_obj, dict):
            raise ValueError("First element in JSON list must be an object (dict).")

        headers = list(first_obj.keys())

        with open(csv_file, 'w', newline='', encoding='utf-8') as f_out:
            writer = csv.DictWriter(f_out, fieldnames=headers)
            writer.writeheader()
            for obj in data:
                if not isinstance(obj, dict):
                    raise ValueError("All elements in JSON list must be objects (dict).")
                writer.writerow(obj)

    except FileNotFoundError:
        raise FileNotFoundError(f"Input file '{json_file}' not found.")
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON format: {e}")
    except Exception as e:
        raise RuntimeError(f"An error occurred during conversion: {e}")
