def normalize_input(input, target_type=None):
    if not isinstance(input, str):
        raise TypeError("Input must be a string.")

    normalized = input.strip().lower().replace(" ", "")

    if target_type is None:
        return normalized

    if target_type == bool:
        if normalized == "true":
            return True
        elif normalized == "false":
            return False
        else:
            raise ValueError(f"Cannot convert '{normalized}' to bool.")

    if target_type == int:
        try:
            return int(normalized)
        except ValueError:
            raise ValueError(f"Cannot convert '{normalized}' to int.")

    if target_type == float:
        try:
            return float(normalized)
        except ValueError:
            raise ValueError(f"Cannot convert '{normalized}' to float.")

    # For other types, attempt direct conversion
    try:
        return target_type(normalized)
    except (ValueError, TypeError) as e:
        raise ValueError(f"Cannot convert '{normalized}' to {target_type.__name__}.") from e
