```python
def normalize_path(path):
    if not path:
        return ''

    # Split the path by slashes, filtering out empty strings from redundant slashes
    parts = [p for p in path.split('/') if p]

    # Stack to build the normalized path
    stack = []

    for part in parts:
        if part == '.':
            # Current directory, ignore
            continue
        elif part == '..':
            # Parent directory, pop from stack if possible
            if stack:
                stack.pop()
        else:
            # Regular directory or file name
            stack.append(part)

    # Reconstruct the path
    if not stack:
        # If the original path started with '/', it's absolute
        if path.startswith('/'):
            return '/'
        return ''

    normalized = '/' + '/'.join(stack) if path.startswith('/') else '/'.join(stack)

    return normalized
```

