def pizza_order_summary(orders):
    from collections import Counter

    # Count occurrences of each (name, size) pair
    counts = Counter()
    for pizza in orders:
        counts[(pizza.name, pizza.size)] += 1

    # Build the summary string
    parts = []
    for (name, size), count in counts.items():
        parts.append(f"{count} {size} {name}")

    return ", ".join(parts)
